// Gelen parametreleri doğrula
const body = $input.item.json.body;

// Required fields
const requiredFields = ['exam_type', 'subject', 'topic', 'difficulty', 'user_id'];
const missingFields = requiredFields.filter(field => !body[field]);

if (missingFields.length > 0) {
  throw new Error(`Eksik parametreler: ${missingFields.join(', ')}`);
}

// Validate exam_type
if (!['TYT', 'AYT'].includes(body.exam_type)) {
  throw new Error('exam_type TYT veya AYT olmalıdır');
}

// Validate difficulty
if (!['Kolay', 'Orta', 'Zor'].includes(body.difficulty)) {
  throw new Error('difficulty Kolay, Orta veya Zor olmalıdır');
}

return { json: body };

const data = $input.item.json;

// Zorluk seviyesi tanımları
const difficultyDescriptions = {
  'Kolay': 'temel seviye bilgi gerektiren, basit hesaplama ve kavramsal sorular',
  'Orta': 'orta seviye düşünme becerisi gerektiren, birden fazla adım içerebilen sorular',
  'Zor': 'ileri seviye analitik düşünme gerektiren, karmaşık ve çok adımlı sorular'
};

// Sınav tipi bilgileri
const examInfo = {
  'TYT': 'Temel Yeterlilik Testi - Temel seviye ve ortak müfredat soruları',
  'AYT': 'Alan Yeterlilik Testi - Daha detaylı ve alan odaklı sorular'
};

// GPT-4o Prompt oluştur
const prompt = `Sen profesyonel bir ${data.exam_type} sınav sorusu hazırlama uzmanısın.

SINAV BİLGİSİ:
${examInfo[data.exam_type]}

SORU KRİTERLERİ:
- Ders: ${data.subject}
- Konu: ${data.topic}
- Zorluk Seviyesi: ${data.difficulty} (${difficultyDescriptions[data.difficulty]})

GÖREVİN:
YKS ${data.exam_type} sınavı standardında, ${data.subject} dersi ${data.topic} konusundan ${data.difficulty} seviyede bir çoktan seçmeli soru oluştur.

KRİTERLER:
1. Soru metni net, anlaşılır ve Türkçe dilbilgisi kurallarına uygun olmalı
2. 5 seçenek (A, B, C, D, E) olmalı
3. Seçenekler birbirine yakın zorlukta ve makul olmalı
4. Yalnızca bir doğru cevap olmalı
5. Çözüm açıklaması adım adım ve öğretici olmalı
6. Matematik soruları için gerekli formüller açıklanmalı

ÇIKTI FORMATI (Sadece JSON, başka metin ekleme):
{
  "question_text": "Soru metni buraya",
  "option_a": "A seçeneği",
  "option_b": "B seçeneği",
  "option_c": "C seçeneği",
  "option_d": "D seçeneği",
  "option_e": "E seçeneği",
  "correct_answer": "A" (sadece harf),
  "explanation": "Detaylı çözüm açıklaması (adım adım)"
}`;

return {
  json: {
    ...data,
    prompt: prompt
  }
};

