parameters.functionCode:
const response = $input.item.json;

// GPT-4o yanıtını parse et
let content = response.choices[0].message.content;

// JSON parse et
let questionData;
try {
  // Eğer markdown code block varsa temizle
  content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  questionData = JSON.parse(content);
} catch (error) {
  throw new Error(`JSON parse hatası: ${error.message}\n\nContent: ${content}`);
}

// Webhook'tan gelen orijinal veriyi al
const originalData = $node['Webhook - Soru İsteği'].json.body;

// Doğru cevabı normalize et (büyük harf yap)
const correctAnswer = questionData.correct_answer.toUpperCase();

// Veritabanı için hazırla
const questionRecord = {
  exam_type: originalData.exam_type,
  subject: originalData.subject,
  topic: originalData.topic,
  difficulty: originalData.difficulty,
  question_text: questionData.question_text,
  option_a: questionData.option_a,
  option_b: questionData.option_b,
  option_c: questionData.option_c,
  option_d: questionData.option_d,
  option_e: questionData.option_e,
  correct_answer: correctAnswer,
  explanation: questionData.explanation,
  generated_by_ai: true,
  created_by_user_id: originalData.user_id
};

return { json: questionRecord };

// Frontend'e döndürülecek yanıt
const savedQuestion = $input.item.json;

return {
  json: {
    success: true,
    message: 'Soru başarıyla oluşturuldu',
    question: savedQuestion,
    timestamp: new Date().toISOString()
  }
};

// Hata yakalama
const error = $input.item.json.error || $input.item.json;

return {
  json: {
    success: false,
    error: error.message || 'Bilinmeyen hata',
    timestamp: new Date().toISOString()
  }
};
